#!/usr/bin/env python3
import json
import os
import re
import zipfile
import xml.etree.ElementTree as ET

JSON_PATH = '/root/project_proposal.json'
WORK_DIR = '/tmp/hwpx_work'
OUT_PATH = '/root/project_proposal_ready.hwpx'

PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def load_data(path: str) -> dict:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def register_namespaces_from_xml_text(xml_text: str) -> None:
    """Register namespaces found in xmlns declarations.

    If we don't register, ElementTree will emit ns0: prefixes on write.
    """
    # xmlns="uri" (default) or xmlns:hp="uri"
    for m in re.finditer(r'\sxmlns(?::(?P<prefix>[A-Za-z_][\w\-.]*))?=[\"\'](?P<uri>[^\"\']+)[\"\']', xml_text):
        prefix = m.group('prefix') or ''
        uri = m.group('uri')
        ET.register_namespace(prefix, uri)


def normalize_budget(v: str) -> str:
    # Keep leading currency symbol (₩), remove commas in the numeric part.
    if not isinstance(v, str):
        v = str(v)
    if v.startswith('₩'):
        return '₩' + v[1:].replace(',', '')
    return v.replace(',', '')


def replace_placeholders(text: str, data: dict) -> tuple[str, bool]:
    missing = set()

    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in data:
            missing.add(key)
            return m.group(0)
        val = data[key]
        if key == '예산':
            return normalize_budget(val)
        return str(val)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    if missing:
        raise ValueError(f"Missing placeholder keys in JSON: {sorted(missing)}")
    return new_text, (new_text != text)


RANGE_RE = re.compile(r'(\d{4})[.\-](\d{1,2})\s*~\s*(\d{4})[.\-](\d{1,2})')
SINGLE_RE = re.compile(r'(\d{4})[.\-](\d{1,2})')


def month_span_from_text(text: str) -> int | None:
    """Extract a YYYY-MM ~ YYYY-MM range or a single YYYY-MM and return inclusive month count."""
    m = RANGE_RE.search(text)
    if m:
        sy, sm, ey, em = map(int, m.groups())
        diff = (ey - sy) * 12 + (em - sm)
        if diff < 0:
            return None
        return diff + 1  # inclusive

    # Single month like (2027-01)
    ms = SINGLE_RE.findall(text)
    if not ms:
        return None

    # If the text contains a range, RANGE_RE would have matched earlier.
    # Pick the last occurrence (most likely the schedule month inside parentheses).
    sy, sm = map(int, ms[-1])
    if not (1 <= sm <= 12):
        return None
    return 1


def append_month_span_if_phase_line(text: str) -> tuple[str, bool]:
    # Target lines that mention 단계1/2/3 (optionally prefixed with 1단계:, etc.)
    if '단계' not in text:
        return text, False
    if re.search(r'\([0-9]+개월\)', text):
        return text, False

    months = month_span_from_text(text)
    if months is None:
        return text, False

    return f"{text} ({months}개월)", True


def iter_paragraph_text_nodes(p: ET.Element, hp_ns: str):
    # Collect all hp:t elements under this paragraph in document order.
    return list(p.findall(f'.//{{{hp_ns}}}t'))


def remove_linesegarray(p: ET.Element, hp_ns: str) -> bool:
    removed = False
    for child in list(p):
        if child.tag == f'{{{hp_ns}}}linesegarray':
            p.remove(child)
            removed = True
    return removed


def collapse_paragraph_runs(p: ET.Element, hp_ns: str, new_text: str) -> None:
    """Put new_text into the first hp:t, remove extra hp:run/hp:t nodes."""
    runs = [c for c in list(p) if c.tag == f'{{{hp_ns}}}run']
    if not runs:
        # No run to carry text; create one.
        run = ET.Element(f'{{{hp_ns}}}run')
        t = ET.SubElement(run, f'{{{hp_ns}}}t')
        t.text = new_text
        p.insert(0, run)
        return

    first_run = runs[0]
    ts = list(first_run.findall(f'.//{{{hp_ns}}}t'))
    if not ts:
        t = ET.SubElement(first_run, f'{{{hp_ns}}}t')
        t.text = new_text
    else:
        ts[0].text = new_text
        for extra_t in ts[1:]:
            extra_t.text = ''

    # Remove all subsequent run elements to avoid split placeholders/layout artifacts.
    for r in runs[1:]:
        p.remove(r)


def process_section_xml(xml_path: str, data: dict) -> bool:
    with open(xml_path, 'r', encoding='utf-8') as f:
        xml_text = f.read()

    register_namespaces_from_xml_text(xml_text)

    tree = ET.ElementTree(ET.fromstring(xml_text))
    root = tree.getroot()

    # HWPML namespace is usually on hp prefix
    hp_ns = 'http://www.hancom.co.kr/hwpml/2010/HWPML'

    changed_any = False

    for p in root.findall(f'.//{{{hp_ns}}}p'):
        t_nodes = iter_paragraph_text_nodes(p, hp_ns)
        if not t_nodes:
            continue

        full_text = ''.join([(t.text or '') for t in t_nodes])
        if not full_text:
            continue

        modified = False
        new_text = full_text

        if '{{' in full_text and '}}' in full_text:
            new_text, did = replace_placeholders(new_text, data)
            modified = modified or did

        # After placeholder substitution, append month span on phase lines.
        # This should apply to lines like "1단계: ... (2026-08 ~ 2026-10)".
        new_text2, did2 = append_month_span_if_phase_line(new_text)
        new_text = new_text2
        modified = modified or did2

        if modified:
            collapse_paragraph_runs(p, hp_ns, new_text)
            remove_linesegarray(p, hp_ns)
            changed_any = True

    if changed_any:
        tree.write(xml_path, encoding='utf-8', xml_declaration=True)

    return changed_any


def rezip_hwpx(work_dir: str, out_path: str) -> None:
    with zipfile.ZipFile(out_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(work_dir):
            for f in files:
                full = os.path.join(root, f)
                arcname = os.path.relpath(full, work_dir)
                zf.write(full, arcname)


def main():
    data = load_data(JSON_PATH)

    contents_dir = os.path.join(WORK_DIR, 'Contents')
    xml_files = []
    for name in os.listdir(contents_dir):
        if name.lower().endswith('.xml'):
            xml_files.append(os.path.join(contents_dir, name))

    if not xml_files:
        raise RuntimeError(f'No XML files found under {contents_dir}')

    changed = []
    for xp in sorted(xml_files):
        if process_section_xml(xp, data):
            changed.append(xp)

    if not changed:
        raise RuntimeError('No changes were applied (no placeholders/phase lines found?).')

    rezip_hwpx(WORK_DIR, OUT_PATH)


if __name__ == '__main__':
    main()

